/* ---------- Zoom bar ---------- */
/* the Whiteboard template's view bar (owner, 27 Nov): undo and redo, zoom out, the level and zoom in, and fit, as Canvas
   toolbar's bar. Minus and plus step the level shown between them, the level resets it to 100%; undo, redo and fit only
   press. At 25% and 400% the step that has nowhere to go greys out and keeps its place */
.zmb{position:relative;display:flex;justify-content:center}
.zmb-live{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.zmb-bar{display:inline-flex;align-items:center;padding:var(--dm-s-1);border-radius:var(--dm-r-pill);background:var(--dm-raised);box-shadow:var(--dm-shadow-pop);white-space:nowrap}
.zmb-bar :focus-visible{border-radius:var(--dm-r-pill)}
.zmb-b{width:32px;height:32px;flex:none;display:grid;place-items:center;border-radius:var(--dm-r-pill);color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
.zmb-z{min-width:48px;height:32px;padding:0 var(--dm-s-1);flex:none;border-radius:var(--dm-r-pill);font-size:12.5px;color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.zmb-b:hover,.zmb-z:hover{background:var(--dm-row);color:var(--dm-fg)}}
.zmb-b[aria-disabled="true"],.zmb-b[aria-disabled="true"]:active{color:var(--dm-dis);background:none;cursor:not-allowed}
@media (hover:hover) and (pointer:fine){.zmb-b[aria-disabled="true"]:hover{color:var(--dm-dis);background:none;cursor:not-allowed}}
.zmb-sep{width:1px;height:16px;margin:0 var(--dm-s-1);flex:none;background:var(--dm-line)}

DM.def('zoom-bar', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{([\w-]+)\}/g, (m, k) => I(k));
  const zo = $('.zmb-zo', r), zi = $('.zmb-zi', r), zl = $('.zmb-zl', r), live = $('.zmb-live', r);
  // the levels minus and plus step through, as the Whiteboard's
  const STEPS = [.25, .33, .5, .67, .75, .9, 1, 1.25, 1.5, 2, 3, 4];
  let z = 1;
  const paint = say => { const p = Math.round(z * 100) + '%';
    zl.textContent = p; zl.setAttribute('aria-label', `Zoom ${p}, zoom to 100%`);
    zo.setAttribute('aria-disabled', String(z <= STEPS[0])); zi.setAttribute('aria-disabled', String(z >= STEPS[STEPS.length - 1]));
    if (say) live.textContent = 'Zoom ' + p; };
  const step = d => { const n = d > 0 ? STEPS.find(x => x > z + .001) : [...STEPS].reverse().find(x => x < z - .001); if (n){ z = n; paint(true); } };
  c.on(zo, 'click', () => step(-1)); c.on(zi, 'click', () => step(1)); c.on(zl, 'click', () => { z = 1; paint(true); });
  // minus, plus and Shift 0 step and reset the level while the focus is in the bar
  c.on($('.zmb-bar', r), 'keydown', e => {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    const a = e.key === '-' || e.key === '−' ? () => step(-1) : e.key === '+' || e.key === '=' ? () => step(1) : e.shiftKey && (e.key === ')' || e.code === 'Digit0') ? () => { z = 1; paint(true); } : null;
    if (a){ e.preventDefault(); a(); }
  });
  paint();
  // the preview's story: zoom in twice, out once, undo, fit, and back to 100%
  c.story(async s => {
    await s.beat(2);
    await s.tap(zi); await s.beat(1.5); await s.tap(zi); await s.beat(2);
    await s.tap(zo); await s.beat(2);
    await s.point($('.zmb-undo', r)); await s.beat(1); await s.tap($('.zmb-undo', r)); await s.beat(2);
    await s.tap($('.zmb-fit', r)); await s.beat(2);
    await s.tap(zl); s.away(); await s.beat(2);
  });
});
